import fs from 'fs';
import fsPromises from 'fs/promises';
import { randomUUID } from 'crypto';
import path from 'path';
import { createLogger } from '../utils/logger';
import { errnoCode } from '../utils/errnoCode';
import {
  isConfinedRelativePath,
  isPathWithinRoot,
} from '../utils/pathContainment';

const log = createLogger('BundleStore');
const METADATA_DIRNAME = '.metadata';

export interface BundleFile {
  path: string;
  content: string;
}

export interface BundleMetadata {
  shareName: string;
  title?: string;
  createdAt: string;
}

const assertSafeBundlePath = (relPath: string): void => {
  if (relPath.length === 0 || !isConfinedRelativePath(relPath)) {
    throw new Error(`BundleStore: invalid bundle path '${relPath}'`);
  }
};

const isExistingTargetError = (err: unknown): boolean => {
  const code = errnoCode(err);
  return code === 'EEXIST' || code === 'ENOTEMPTY' || code === 'EISDIR';
};

const writeBundleFiles = async (
  bundleRoot: string,
  files: BundleFile[],
): Promise<void> => {
  for (const file of files) {
    assertSafeBundlePath(file.path);
    const target = path.join(bundleRoot, file.path);
    if (!isPathWithinRoot(bundleRoot, target)) {
      throw new Error(`BundleStore: path escapes bundle root '${file.path}'`);
    }
    await fsPromises.mkdir(path.dirname(target), { recursive: true });
    await fsPromises.writeFile(target, Buffer.from(file.content, 'base64'));
  }
};

export interface BundleStore {
  put(deployId: string, files: BundleFile[]): Promise<void>;
  putIfAbsent(
    deployId: string,
    files: BundleFile[],
    metadata: BundleMetadata,
  ): Promise<boolean>;
  read(deployId: string, assetPath: string): Promise<Buffer | null>;
  has(deployId: string): Promise<boolean>;
  rootFor(deployId: string): string;
  getMetadata(deployId: string): Promise<BundleMetadata | null>;
}

export class DiskBundleStore implements BundleStore {
  constructor(private readonly root: string) {}

  rootFor(deployId: string): string {
    return path.join(this.root, deployId);
  }

  private metadataRoot(): string {
    return path.join(this.root, METADATA_DIRNAME);
  }

  private metadataPath(deployId: string): string {
    return path.join(this.metadataRoot(), `${deployId}.json`);
  }

  private createStagingRoot(deployId: string): string {
    return path.join(
      this.root,
      `${deployId}.tmp-${process.pid}-${Date.now()}-${randomUUID()}`,
    );
  }

  async put(deployId: string, files: BundleFile[]): Promise<void> {
    const bundleRoot = this.rootFor(deployId);
    const stagingRoot = this.createStagingRoot(deployId);
    await fsPromises.rm(stagingRoot, { recursive: true, force: true });
    await fsPromises.mkdir(stagingRoot, { recursive: true });
    try {
      await writeBundleFiles(stagingRoot, files);
      await fsPromises.rm(bundleRoot, { recursive: true, force: true });
      await fsPromises.rename(stagingRoot, bundleRoot);
      log.info(`Stored bundle ${deployId} (${files.length} files)`);
    } catch (err) {
      await fsPromises.rm(stagingRoot, { recursive: true, force: true });
      throw err;
    }
  }

  async putIfAbsent(
    deployId: string,
    files: BundleFile[],
    metadata: BundleMetadata,
  ): Promise<boolean> {
    const bundleRoot = this.rootFor(deployId);
    const stagingRoot = this.createStagingRoot(deployId);
    const metadataRoot = this.metadataRoot();
    const metadataTempPath = path.join(
      metadataRoot,
      `${deployId}.tmp-${process.pid}-${Date.now()}-${randomUUID()}.json`,
    );
    let isStored = false;
    let isBundleCommitted = false;
    await fsPromises.mkdir(stagingRoot, { recursive: true });
    try {
      await writeBundleFiles(stagingRoot, files);
      await fsPromises.mkdir(metadataRoot, { recursive: true });
      await fsPromises.writeFile(
        metadataTempPath,
        `${JSON.stringify(metadata, null, 2)}\n`,
        'utf8',
      );
      try {
        await fsPromises.rename(stagingRoot, bundleRoot);
      } catch (err) {
        if (isExistingTargetError(err)) {
          return false;
        }
        throw err;
      }
      isBundleCommitted = true;
      await fsPromises.rename(metadataTempPath, this.metadataPath(deployId));
      isStored = true;
      log.info(`Stored bundle ${deployId} (${files.length} files)`);
      return true;
    } finally {
      if (!isStored) {
        if (isBundleCommitted) {
          await fsPromises.rm(bundleRoot, { recursive: true, force: true });
        }
        await fsPromises.rm(stagingRoot, { recursive: true, force: true });
        await fsPromises.rm(metadataTempPath, { force: true });
      }
    }
  }

  async has(deployId: string): Promise<boolean> {
    try {
      const stat = await fsPromises.stat(this.rootFor(deployId));
      return stat.isDirectory();
    } catch {
      return false;
    }
  }

  async read(deployId: string, assetPath: string): Promise<Buffer | null> {
    assertSafeBundlePath(assetPath);
    const bundleRoot = this.rootFor(deployId);
    const target = path.join(bundleRoot, assetPath);
    if (!isPathWithinRoot(bundleRoot, target)) return null;
    try {
      const stat = await fsPromises.stat(target);
      if (!stat.isFile()) return null;
      return await fsPromises.readFile(target);
    } catch (err) {
      const code = errnoCode(err);
      if (code !== 'ENOENT') {
        log.warn(`read failed for ${deployId}/${assetPath}`, err);
      }
      return null;
    }
  }

  async getMetadata(deployId: string): Promise<BundleMetadata | null> {
    try {
      const raw = await fsPromises.readFile(
        this.metadataPath(deployId),
        'utf8',
      );
      return JSON.parse(raw) as BundleMetadata;
    } catch {
      return null;
    }
  }
}

export const ensureBundleRoot = async (root: string): Promise<void> => {
  await fsPromises.mkdir(root, { recursive: true });
  if (!fs.existsSync(root)) {
    throw new Error(`BundleStore: bundle root '${root}' could not be created`);
  }
};
